// What the payload lets a filler upload.
//
// The model writes form answers after reading the job posting -- untrusted
// text. An answer for a file field is a path the filler attaches, so a
// posting could ask for any file on this computer. The payload therefore
// keeps no model answer for a file field: the résumé is injected from the
// user's own setting, the cover letter is generated by the filler, and the
// payload names the résumé (resume_path) so the Python side can refuse
// anything else (job_application_automator/upload_guard.py).
//
// Run: npm run test:unit
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')
const Module = require('module')

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'payload-uploads-'))
const resume = path.join(tmp, 'Alex Rivera.pdf')
fs.writeFileSync(resume, '%PDF-1.4')
const settings = { jobAutomatorHome: tmp, resumePath: resume }

const load = Module._load
Module._load = function (request, ...rest) {
  if (request.endsWith('state-store')) {
    return { __esModule: true, default: { get: k => settings[k], set: () => {} } }
  }
  return load.call(this, request, ...rest)
}
const { modelAnswersForForm, buildAndWritePayload } = require('../../out/unit/electron/payload-builder.js')

const fields = [
  { id: 'name', type: 'text', required: true, label: 'Full name' },
  { id: 'resume', type: 'file', required: true, label: 'Resume' },
  { id: 'cover_letter', type: 'file', required: false, label: 'Cover Letter' },
  { id: 'why', type: 'textarea', required: false, label: 'Why us?' },
]

test('model answers for file fields and unknown fields are dropped; the rest are kept', () => {
  const kept = modelAnswersForForm(fields, {
    name: 'Alex Rivera',
    resume: 'C:/Users/someone/.codex/auth.json',
    cover_letter: '~/.claude/.credentials.json',
    why: 'Because.',
    not_a_field: 'x',
  })
  assert.deepEqual(kept, { name: 'Alex Rivera', why: 'Because.' })
})

test('the written payload carries the résumé from settings, never a model path', async () => {
  const job = {
    platform: 'lever',
    job_id: 'job-1',
    apply_url: 'https://jobs.example.com/northwind/job-1/apply',
    extracted_fields: { fields },
  }
  const built = await buildAndWritePayload(job, {
    name: 'Alex Rivera',
    resume: 'C:/Users/someone/.codex/auth.json',
    cover_letter: 'C:/Users/someone/secrets/imap_config.json',
  })
  const payloadPath = built.payloadPath ?? path.join(tmp, 'applications', 'lever', 'job-1', 'fill_payload.json')
  const written = JSON.parse(fs.readFileSync(payloadPath, 'utf-8'))
  assert.equal(written.resume_path, resume)
  assert.equal(written.answers.resume, resume)
  assert.equal(written.answers.cover_letter, undefined)
  assert.equal(written.answers.name, 'Alex Rivera')
})
